    expect(read(root, '.prettierignore')).toBe('dist\n.sofar/\n')
    runDoctor(root, { fix: true })
    expect(read(root, '.prettierignore')).toBe('dist\n.sofar/\n')

    for (const line of ['.sofar', '/.sofar/', '**/.sofar/**']) {
